@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           placeholder="Search products..."
           @oninput="OnSearchInput"
           class="product-search-input" />

    @if (_isLoading)
    {
        <div class="product-search-status">Searching...</div>
    }
    else if (_errorMessage is not null)
    {
        <div class="product-search-error">@_errorMessage</div>
    }
    else if (_hasSearched && _results.Count == 0)
    {
        <div class="product-search-status">No products found.</div>
    }

    @if (_results.Count > 0)
    {
        <div class="product-search-results">
            @foreach (var product in _results)
            {
                <div class="product-card" @onclick="() => SelectProduct(product)">
                    <img src="@product.ImageUrl" alt="@product.Name" class="product-card-image" />
                    <div class="product-card-name">@product.Name</div>
                    <div class="product-card-price">@product.Price.ToString("C")</div>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private List<Product> _results = new();
    private bool _isLoading;
    private bool _hasSearched;
    private string? _errorMessage;

    private Timer? _debounceTimer;
    private CancellationTokenSource? _searchCts;
    private string _currentQuery = string.Empty;

    private void OnSearchInput(ChangeEventArgs e)
    {
        _currentQuery = e.Value?.ToString() ?? string.Empty;

        _debounceTimer?.Dispose();
        _debounceTimer = new Timer(OnDebounceElapsed, null, 300, Timeout.Infinite);
    }

    private async void OnDebounceElapsed(object? state)
    {
        await InvokeAsync(async () =>
        {
            var query = _currentQuery;

            if (string.IsNullOrWhiteSpace(query))
            {
                _results = new();
                _hasSearched = false;
                _errorMessage = null;
                _isLoading = false;
                StateHasChanged();
                return;
            }

            // Cancel any in-flight search
            _searchCts?.Cancel();
            _searchCts?.Dispose();
            _searchCts = new CancellationTokenSource();
            var ct = _searchCts.Token;

            _isLoading = true;
            _errorMessage = null;
            StateHasChanged();

            try
            {
                var results = await ProductService.SearchAsync(query, ct);
                ct.ThrowIfCancellationRequested();

                _results = results;
                _hasSearched = true;
                _errorMessage = null;
            }
            catch (OperationCanceledException)
            {
                // Search was superseded by a newer query; do nothing.
                return;
            }
            catch (Exception)
            {
                _results = new();
                _errorMessage = "Something went wrong. Please try again.";
            }
            finally
            {
                if (!ct.IsCancellationRequested)
                {
                    _isLoading = false;
                }
            }

            StateHasChanged();
        });
    }

    private async Task SelectProduct(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    public void Dispose()
    {
        _debounceTimer?.Dispose();
        _searchCts?.Cancel();
        _searchCts?.Dispose();
    }
}

